"""Textos propios del complemento en 51 idiomas y reglas de plural.

Lo que Anki ya trae traducido (N/A, Anadir, Eliminar, Buscar) se toma de
Anki con anki_text. Las cifras, fechas, meses e iniciales de los dias los
escribe el navegador con Intl en el idioma de Anki.
"""

