def norm_lang(code: str) -> str:
    code = code.replace("-", "_")
    if code[:2].lower() == "zh":
        return "zh_TW" if any(tag in code.upper() for tag in ("TW", "HK", "MO")) else "zh_CN"
    return code.split("_")[0].lower()


def raw_lang_code() -> str:
    """Codigo de idioma tal cual lo tiene Anki, p. ej. "es" o "pt-BR"."""
    try:
        import anki.lang

        raw_code = getattr(anki.lang, "current_lang", "")
        return raw_code if isinstance(raw_code, str) else ""
    except Exception:
        return ""


# El idioma de Anki solo cambia reiniciando, pero se guarda en cache y se
# invalida con reset() al abrir un perfil: asi t() no repite el trabajo de
# resolucion en cada una de las ~400 llamadas que hace un dibujado completo.
_lang_cache: str | None = None


def lang() -> str:
    global _lang_cache
    if _lang_cache is None:
        key = norm_lang(raw_lang_code())
        _lang_cache = key if key in STRINGS else "en"
    return _lang_cache


def reset() -> None:
    """Olvida el idioma cacheado (se llama al abrir o cambiar de perfil)."""
    global _lang_cache
    _lang_cache = None


def t(key: str) -> str:
    return STRINGS[lang()].get(key, STRINGS["en"].get(key, key))


def fill(key: str, **values: object) -> str:
    """Sustituye los huecos {nombre} de un texto propio del complemento."""
    text = t(key)
    for name, value in values.items():
        text = text.replace("{" + name + "}", str(value))
    return text


def locale_code() -> str:
    """Etiqueta BCP-47 para Intl en el navegador (p. ej. "es" o "zh-CN")."""
    raw = raw_lang_code().replace("_", "-")
    return raw or "en"


def unit_label(value: int, unit: str) -> str:
    """Unidad con la forma de plural que pide la cifra: dia, dias; день, дня, дней."""
    # --- FIX-022 (2026-10-13) --------------------------------------
    # Sintoma: en ruso salia «Racha actual: 22 дней» en lugar de «22 дня», y
    #          lo mismo con repasos, tarjetas y cuentas atras en otros doce
    #          idiomas.
    # Causa: aqui solo se distinguia «una» de «varias»; ruso, polaco, checo,
    #        arabe y otros tienen tres o mas formas.
    # Regla: toda cifra con unidad elige su forma con plural_category (reglas
    #        CLDR, las mismas del navegador); si un idioma no tiene una forma,
    #        se usa su forma general (_other).
    # ---------------------------------------------------------------
    return plural_text(f"unit_{unit}", value)


# Plurales completos (reglas CLDR para numeros enteros, las mismas que usa el
# navegador con Intl.PluralRules). Desde 3.2.0 valen para todas las cifras con
# unidad (FIX-022), no solo para «Nuevas». Las formas de "millones" que CLDR
# tiene en algunos idiomas no se contemplan: ninguna cifra del mapa llega ahi.
PLURAL_CATEGORIES: tuple[str, ...] = ("zero", "one", "two", "few", "many", "other")

_ONLY_OTHER = {"ja", "ko", "zh_CN", "zh_TW", "vi", "th", "ms", "jbo"}
_ONE_FOR_ZERO_AND_ONE = {"fr", "pt", "hy", "fa"}


def _slavic_east(n: int) -> str:
    if n % 10 == 1 and n % 100 != 11:
        return "one"
    if 2 <= n % 10 <= 4 and not 12 <= n % 100 <= 14:
        return "few"
    return "many"


def plural_category(code: str, n: int) -> str:
    """Forma de plural que pide un numero entero no negativo en un idioma."""
    n = abs(n)
    if code in _ONLY_OTHER:
        return "other"
    if code in _ONE_FOR_ZERO_AND_ONE:
        return "one" if n in (0, 1) else "other"
    if code in ("ru", "uk", "be"):
        return _slavic_east(n)
    if code == "pl":
        if n == 1:
            return "one"
        return "few" if _slavic_east(n) == "few" else "many"
    if code in ("cs", "sk"):
        if n == 1:
            return "one"
        return "few" if 2 <= n <= 4 else "other"
    if code in ("hr", "sr"):
        category = _slavic_east(n)
        return "other" if category == "many" else category
    if code == "sl":
        return {1: "one", 2: "two", 3: "few", 4: "few"}.get(n % 100, "other")
    if code == "ro":
        if n == 1:
            return "one"
        return "few" if n == 0 or 1 <= n % 100 <= 19 else "other"
    if code == "ar":
        if n in (0, 1, 2):
            return ("zero", "one", "two")[n]
        if 3 <= n % 100 <= 10:
            return "few"
        return "many" if 11 <= n % 100 <= 99 else "other"
    if code == "he":
        return {1: "one", 2: "two"}.get(n, "other")
    if code == "ga":
        if n in (1, 2):
            return ("one", "two")[n - 1]
        if 3 <= n <= 6:
            return "few"
        return "many" if 7 <= n <= 10 else "other"
    if code == "tl":
        return "other" if n % 10 in (4, 6, 9) else "one"
    return "one" if n == 1 else "other"


def plural_form(base: str, category: str) -> str:
    """Texto propio de una forma de plural concreta.

    Si el idioma no tiene esa forma, se usa su forma general ("other"); si
    tampoco la tiene, la del ingles.
    """
    texts = STRINGS[lang()]
    english = STRINGS["en"]
    return (
        texts.get(f"{base}_{category}")
        or texts.get(f"{base}_other")
        or english.get(f"{base}_{category}")
        or english.get(f"{base}_other", "")
    )


def plural_key(base: str, count: int) -> str:
    """Nombre de la clave con la forma de plural que corresponde a count."""
    code = lang()
    texts = STRINGS[code]
    for key in (f"{base}_{plural_category(code, count)}", f"{base}_other"):
        if key in texts:
            return key
    return f"{base}_one" if abs(count) == 1 else f"{base}_other"


def plural_text(base: str, count: int) -> str:
    """Texto propio con la forma de plural que corresponde a count."""
    return t(plural_key(base, count))


# Textos que Anki ya trae traducidos a todos sus idiomas. Se leen de la propia
# coleccion de traducciones de Anki en lugar de duplicarlos aqui, de modo que
# siempre coincidan con lo que la persona ve en el resto del programa. Si una
# version de Anki dejara de exponer alguna clave, se usa el texto propio.
def anki_text(attribute: str, fallback_key: str) -> str:
    try:
        from aqt.utils import tr

        method = getattr(tr, attribute, None)
        if callable(method):
            value = method()
            if isinstance(value, str) and value.strip():
                return value
    except Exception:
        pass
    return t(fallback_key)


def month_abbrev(month: int) -> str:
    """Abreviatura del mes.

    Es solo la reserva: el navegador reescribe estas etiquetas con Intl, que
    conoce los nombres de mes de cualquier idioma que soporte Anki.
    """
    table = _MONTHS.get(lang(), _MONTHS["en"])
    if 1 <= month <= 12:
        return table[month - 1]
    return ""

